package com.streak.app
import android.app.*;import android.content.*;import android.os.Build;import androidx.core.app.NotificationCompat;import java.util.concurrent.TimeUnit
class ReminderReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val p=c.getSharedPreferences("morynth",Context.MODE_PRIVATE);val s=p.getLong("startMs",0L);if(s==0L)return;val d=TimeUnit.MILLISECONDS.toDays(System.currentTimeMillis()-s);val n=c.getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager;if(Build.VERSION.SDK_INT>=26)n.createNotificationChannel(NotificationChannel("daily","Morynth reminder",NotificationManager.IMPORTANCE_DEFAULT));n.notify(830,NotificationCompat.Builder(c,"daily").setSmallIcon(android.R.drawable.ic_popup_reminder).setContentTitle("Morynth ◆ Keep rising").setContentText("Your journey is now "+d+" days strong.").setAutoCancel(true).build())}}